    "text": "package rpc

// callerDeadlineQueue indexes only specialized admitted owners. Keeping the
// index here avoids enlarging every Request/entry, including read RPCs.
// Service.mu protects both queue-bounded collections; removal clears references.
type callerDeadlineQueue struct {
	entries   []*requestEntry
	positions map[*requestEntry]int
}

func (q callerDeadlineQueue) Len() int { return len(q.entries) }
func (q callerDeadlineQueue) Less(i, j int) bool {
	a, _ := q.entries[i].req.Context.Deadline()
	b, _ := q.entries[j].req.Context.Deadline()
	return a.Before(b)
}
func (q callerDeadlineQueue) Swap(i, j int) {
	q.entries[i], q.entries[j] = q.entries[j], q.entries[i]
	q.positions[q.entries[i]] = i
	q.positions[q.entries[j]] = j
}
func (q *callerDeadlineQueue) Push(value any) {
	e := value.(*requestEntry)
	if q.positions == nil {
		q.positions = make(map[*requestEntry]int)
	}
	q.positions[e] = len(q.entries)
	q.entries = append(q.entries, e)
}
func (q *callerDeadlineQueue) Pop() any {
	n := len(q.entries) - 1
	e := q.entries[n]
	q.entries[n] = nil
	q.entries = q.entries[:n]
	delete(q.positions, e)
	return e
}
"
