    "text": "//go:build integration

package rpc

import (
	"context"
	"errors"
	"github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
	"testing"
	"testing/synctest"
	"time"
)

type countedQueueSource struct{ installs int }

func (s *countedQueueSource) WatchInboundQueue(_ uint64, ctx context.Context, f func()) func() bool {
	s.installs++
	return context.AfterFunc(ctx, f)
}

// The specialized source must not be touched before admission or for reads.
func TestInboundQueueWatchAdmissionBoundary(t *testing.T) {
	for _, kind := range []string{"mutation", "read", "unbudgeted", "busy", "too_large", "canceled", "stopped"} {
		t.Run(kind, func(t *testing.T) {
			synctest.Test(t, func(t *testing.T) {
				root, cancel := context.WithCancel(context.Background())
				defer cancel()
				s := &Service{ctx: root, cancel: cancel, opts: normalizeServiceOptions(core.ServiceOptions{QueueSize: 1, MaxQueueBytes: 64, MaxPayload: 64, CancelRunning: kind == "read"}), queueReady: make(chan struct{}, 1), done: make(chan struct{})}
				defer s.Stop()
				ctx, finish := context.WithTimeout(context.Background(), time.Hour)
				defer finish()
				var requestCtx context.Context = ctx
				if kind == "unbudgeted" {
					requestCtx = context.Background()
				}
				var want error
				payload := core.NewOwnedBuffer([]byte("data"), nil)
				switch kind {
				case "busy":
					if err := s.Enqueue(Request{}); err != nil {
						t.Fatal(err)
					}
					want = core.ErrBusy
				case "too_large":
					payload = core.NewOwnedBuffer(make([]byte, 65), nil)
					want = core.ErrMsgTooLarge
				case "canceled":
					finish()
					want = core.ErrCanceled
				case "stopped":
					s.Stop()
					want = core.ErrStopped
				}
				source := &countedQueueSource{}
				if err := s.EnqueueInbound(Request{Context: requestCtx, Payload: payload}, 1, source); !errors.Is(err, want) {
					t.Fatalf("got=%v want=%v", err, want)
				}
				expected := 0
				if kind == "mutation" {
					expected = 1
				}
				if source.installs != expected {
					t.Fatalf("%s installed %d hooks, want %d", kind, source.installs, expected)
				}
			})
		})
	}
}
