  "pkg/transport/internal/conn/admitted_queue_test.go": "package conn

import (
	"context"
	"sync/atomic"
	"testing"
	"testing/synctest"
	"time"
)

// Installation must not strand a queue hook behind a cancel function that a
// concurrent CancelInbound has already selected. Fake time pins this ordering.
func TestAdmittedQueueWatchDuringCancel(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		parent, cancelParent := context.WithCancel(context.Background())
		defer cancelParent()
		c := &Conn{ctx: parent}
		ctx, finish, err := c.TrackInbound(1, time.Hour)
		if err != nil {
			t.Fatal(err)
		}
		defer finish()
		selected, release, canceled := make(chan struct{}), make(chan struct{}), make(chan struct{})
		original := c.inboundRequests[1]
		c.inboundRequests[1] = func() { close(selected); <-release; original() }
		go func() { c.CancelInbound(1); close(canceled) }()
		<-selected
		var calls atomic.Int32
		var stop func() bool
		// Mutex waits are not durable blocking events in synctest. If cancellation
		// permits installation while its selected function is running, install first;
		// otherwise release cancellation and let the serialized installation proceed.
		if c.inboundWatchMu.TryLock() {
			c.inboundWatchMu.Unlock()
			stop = c.WatchInboundQueue(1, ctx, func() { calls.Add(1) })
			close(release)
			<-canceled
		} else {
			installed := make(chan func() bool, 1)
			go func() { installed <- c.WatchInboundQueue(1, ctx, func() { calls.Add(1) }) }()
			close(release)
			<-canceled
			stop = <-installed
		}
		synctest.Wait()
		if calls.Load() != 1 {
			t.Fatalf("in-flight cancellation missed installed queue hook: calls=%d", calls.Load())
		}
		if stop() {
			t.Fatal("terminal hook remained detachable")
		}
	})
}

func TestAdmittedQueueWatchTerminalOrdering(t *testing.T) {
	for _, terminal := range []string{"cancel_before", "cancel_after", "close_before", "close_after", "finish_before", "detach"} {
		t.Run(terminal, func(t *testing.T) {
			synctest.Test(t, func(t *testing.T) {
				parent, cancel := context.WithCancel(context.Background())
				defer cancel()
				c := &Conn{ctx: parent}
				ctx, finish, err := c.TrackInbound(1, time.Hour)
				if err != nil {
					t.Fatal(err)
				}
				defer finish()
				switch terminal {
				case "cancel_before":
					c.CancelInbound(1)
				case "close_before":
					cancel()
					c.cancelInboundRequests()
				case "finish_before":
					finish()
				}
				var calls atomic.Int32
				stop := c.WatchInboundQueue(1, ctx, func() {
					if ctx.Err() == nil {
						t.Error("callback ran before context cancellation")
					}
					calls.Add(1)
				})
				switch terminal {
				case "cancel_after":
					c.CancelInbound(1)
				case "close_after":
					cancel()
					c.cancelInboundRequests()
				case "detach":
					if !stop() {
						t.Fatal("could not detach")
					}
					finish()
				}
				synctest.Wait()
				want := int32(1)
				if terminal == "detach" {
					want = 0
				}
				if calls.Load() != want {
					t.Fatalf("calls=%d want=%d", calls.Load(), want)
				}
				if stop() {
					t.Fatal("terminal watch still detachable")
				}
			})
		})
	}
}
